	db JOHTO_NEW_BARK_LOCAL_ID, JOHTO_ROUTE_29_LOCAL_ID, JOHTO_CHERRYGROVE_LOCAL_ID, JOHTO_ROUTE_30_LOCAL_ID, JOHTO_ROUTE_31_LOCAL_ID, 6, 7, 8, 13, 14, 15, 16, 17, 18, 19, 20 ; $00-$0f
