	db JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT, 57, 58, JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT, 47, JOHTO_INVALID_ACTIVE_SLOT, 5, JOHTO_INVALID_ACTIVE_SLOT, JOHTO_INVALID_ACTIVE_SLOT ; $70-$7f (Union Cave B1F ID114 slot57, B2F ID115 slot58)
